require dirname(__DIR__).'/bootstrap.php';method('GET');$tid=number('tid');$t=one('SELECT t.* FROM '.table('forum_thread').' t WHERE '.thread_where().' AND t.tid=?',[$tid]);if(!$t)respond(null,404,'帖子不存在或没有阅读权限');
$pt=table('forum_post'.((int)$t['posttableid']?'_'.(int)$t['posttableid']:''));$p=one('SELECT * FROM '.$pt.' WHERE tid=? AND first=1 AND invisible=0',[$tid]);if(!$p)respond(null,404,'正文不可访问');$d=card($t);$d=array_intersect_key($d,array_flip(['tid','fid','subject','author','authorid','avatar','dateline','views','replies','digest']));$d['pid']=(int)$p['pid'];$d['content_html']=render_post($p,$t);$d['attachments']=$GLOBALS['app_render_attachments']??[];
$u=current_user();$uid=(int)($u['uid']??0);$hidden=((int)$t['status']&2)&&$uid!==(int)$t['authorid'];$filter=$hidden?' AND authorid='.$uid:'';$count=one('SELECT COUNT(*) n FROM '.$pt.' WHERE tid=? AND first=0 AND invisible=0'.$filter,[$tid]);$page=paging($count['n']);$offset=($page['page']-1)*20;$rs=rows('SELECT * FROM '.$pt.' WHERE tid=? AND first=0 AND invisible=0'.$filter.' ORDER BY dateline,pid LIMIT '.$offset.',20',[$tid]);$reply=[];foreach($rs as $r)$reply[]=['pid'=>(int)$r['pid'],'author'=>$r['anonymous']?'匿名':$r['author'],'authorid'=>$r['anonymous']?0:(int)$r['authorid'],'dateline'=>$r['dateline'],'content_html'=>render_post($r,$t),'attachments'=>$GLOBALS['app_render_attachments']??[]];$d['reply_list']=$reply;$d['reply_page']=$page;
$d['favorited']=false;$d['liked']=false;$d['likes']=0;if($u){app_schema();$d['favorited']=(bool)one('SELECT uid FROM '.table('app_favorite').' WHERE uid=? AND tid=?',[$uid,$tid]);$d['liked']=(bool)one('SELECT uid FROM '.table('app_like').' WHERE uid=? AND tid=?',[$uid,$tid]);$d['likes']=(int)one('SELECT COUNT(*) n FROM '.table('app_like').' WHERE tid=?',[$tid])['n'];}
